function flattenTree(nodes) {
    const out = [];
    const walk = (list) => {
        for (const node of list) {
            out.push(node);
            if (node.children)
                walk(node.children);
        }
    };
    walk(nodes);
    return out;
}
function treeCodes(nodes = exports.APPROVED_TREE) {
    return flattenTree(nodes).map((n) => n.code);
}
function topLevelCodes(nodes = exports.APPROVED_TREE) {
    return nodes.map((n) => n.code);
}
